{"command": "cat << 'EOF' > plot_weighted_latency.py
import matplotlib.pyplot as plt

# Data for each service
services = {
    "auth": {
        "region_A": {"requests": 100, "latency": 120},
        "region_B": {"requests": 300, "latency": 80}
    },
    "search": {
        "region_A": {"requests": 250, "latency": 60},
        "region_B": {"requests": 250, "latency": 100}
    },
    "checkout": {
        "region_A": {"requests": 50, "latency": 200},
        "region_B": {"requests": 450, "latency": 40}
    },
    "media": {
        "region_A": {"requests": 400, "latency": 150},
        "region_B": {"requests": 100, "latency": 50}
    }
}

# Calculate request-weighted mean latency for each service
weighted_latencies = {}
for service, regions in services.items():
    total_requests = sum(region["requests"] for region in regions.values())
    weighted_sum = sum(region["requests"] * region["latency"] for region in regions.values())
    weighted_latencies[service] = weighted_sum / total_requests

# Order of services for plotting
order = ["auth", "search", "checkout", "media"]

# Plotting
plt.figure(figsize=(8, 6))
bars = plt.bar(order, [weighted_latencies[service] for service in order], color='skyblue')

# Add values above each bar
for bar in bars:
    height = bar.get_height()
    plt.text(bar.get_x() + bar.get_width() / 2., 
             height,
             f'{height:.1f}',
             ha='center', va='bottom')

# Set labels and title
plt.title("Request-weighted mean latency by service")
plt.xlabel("Service")
plt.ylabel("Latency (ms)")
plt.ylim(0, None)  # Ensure y-axis starts at zero

# Save the figure
plt.savefig("figure.png")
plt.close()
EOF"}

